    "answer": "sfr：定义 8 位特殊功能寄存器，如 sfr P1 = 0x90。sbit：定义可位寻址的位变量，常用于访问 SFR 的某一位，如 sbit LED = P1^0。bit：定义 1 位变量，存储在位寻址区（20H-2FH），取值 0 或 1。三者都是 C51 特有，用于直接操作 8051 硬件。",
