    "q": "第 11 章 显示与接口技术 实验中如何调试？",
    "answer": "调试方法：1) 使用 ST-Link/J-Link 在线调试，设断点观察变量；2) 通过串口 printf 打印调试信息；3) 使用示波器观察引脚波形；4) 使用逻辑分析仪分析通信协议；5) 通过 LED 指示程序运行状态。",
