    "q": "第 15 章 STM32 HAL 库 有哪些常见错误及解决方法？",
    "answer": "常见错误：1) 引脚配置错误（检查 GPIO 模式和复用）；2) 时钟未使能（检查 RCC 配置）；3) 中断优先级设置错误（检查 NVIC）；4) 库函数调用顺序错误（先 init 再使用）；5) 硬件接线错误（用万用表检查）。解决方法：仔细对照数据手册，逐步排查。",
    "explain": "系统化排查问题。"
